const N = 896;
type Vec = keyof typeof VECTORS;

// ---------------------------------------------------------------- formats

type Elem = "int4" | "e2m1" | "e4m3";
type ScaleFmt = "fp32" | "fp16" | "e8m0" | "e4m3";
type Preset = "int4-row" | "int4-g128" | "mxfp4" | "nvfp4" | "fp8-row" | "custom";

const roundEven = (a: number) => {
  const f = Math.floor(a), d = a - f;
  return d > 0.5 ? f + 1 : d < 0.5 ? f : f % 2 === 0 ? f : f + 1;
};

// floor(log2 a), exact at powers of two.
function ilog2(a: number): number {
  let E = Math.floor(Math.log2(a));
  if (2 ** E > a) E--;
  if (2 ** (E + 1) <= a) E++;
  return E;
}

// Nearest value of a binary floating-point format with m mantissa bits and
// smallest normal exponent emin (subnormals below it), ties to even,
// saturating at ±max.
function roundFloat(v: number, m: number, emin: number, max: number): number {
  if (v === 0) return 0;
  const a = Math.abs(v);
  const q = 2 ** (Math.max(ilog2(a), emin) - m);
  return Math.sign(v) * Math.min(roundEven(a / q) * q, max);
}
const fp16 = (v: number) => roundFloat(v, 10, -14, 65504);
const e4m3 = (v: number) => roundFloat(v, 3, -6, 448);

// over: half the spacing a next element above q_max would have (8 for INT4
// and E2M1, 480 for E4M3). A value beyond q_max + over is clipped: saturation
// left it farther from x than rounding would have.
interface ElemSpec { bits: number; qmax: number; emax: number; over: number; round(y: number): number }
const ELEM: Record<Elem, ElemSpec> = {
  int4: { bits: 4, qmax: 7, emax: 2, over: 0.5, round: (y) => Math.max(-7, Math.min(7, roundEven(y))) },
  e2m1: { bits: 4, qmax: 6, emax: 2, over: 1, round: (y) => roundFloat(y, 1, 0, 6) },
  e4m3: { bits: 8, qmax: 448, emax: 8, over: 16, round: (y) => e4m3(y) },
};
const SCALE_BITS: Record<ScaleFmt, number> = { fp32: 32, fp16: 16, e8m0: 8, e4m3: 8 };

// Non-negative element values, ascending.
function elementValues(e: Elem): number[] {
  if (e === "int4") return [0, 1, 2, 3, 4, 5, 6, 7];
  if (e === "e2m1") return [0, 0.5, 1, 1.5, 2, 3, 4, 6];
  const out = [0];
  for (let k = 1; k < 8; k++) out.push(k * 2 ** -9);
  for (let E = -6; E <= 8; E++) for (let mm = 0; mm < 8; mm++) { const v = (1 + mm / 8) * 2 ** E; if (v <= 448) out.push(v); }
  return out;
}

const PRESETS: Record<Exclude<Preset, "custom">, { elem: Elem; group: number; scale: ScaleFmt }> = {
  "int4-row": { elem: "int4", group: N, scale: "fp16" },
  "int4-g128": { elem: "int4", group: 128, scale: "fp16" },
  mxfp4: { elem: "e2m1", group: 32, scale: "e8m0" },
  nvfp4: { elem: "e2m1", group: 16, scale: "e4m3" },
  "fp8-row": { elem: "e4m3", group: N, scale: "fp32" },
};
const PRESET_KEYS = Object.keys(PRESETS) as Array<Exclude<Preset, "custom">>;

// ---------------------------------------------------------------- model

interface Group { k: number; start: number; end: number; amax: number; s: number; enc: number; clipped: number; maxErr: number }
interface Result { xhat: number[]; err: number[]; clip: boolean[]; groups: Group[]; rel: number; bEff: number; sT: number; maxErr: number }

function quantize(x: number[], elem: Elem, size: number, sf: ScaleFmt): Result {
  const E = ELEM[elem];
  const amaxT = x.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  const sT = Math.fround(amaxT / (E.qmax * 448));
  const xhat: number[] = new Array(x.length), err: number[] = new Array(x.length), clip: boolean[] = new Array(x.length);
  const groups: Group[] = [];
  let se = 0, sx = 0, maxErr = 0;
  for (let start = 0, k = 0; start < x.length; start += size, k++) {
    const end = Math.min(x.length, start + size);
    let amax = 0;
    for (let i = start; i < end; i++) amax = Math.max(amax, Math.abs(x[i]));
    let s = 1, enc = 0; // an all-zero group stores s = 1 and zero codes (the chapter's convention)
    if (amax > 0) {
      if (sf === "fp32") s = Math.fround(amax / E.qmax);
      else if (sf === "fp16") s = fp16(amax / E.qmax);
      else if (sf === "e8m0") s = 2 ** (ilog2(amax) - E.emax);
      else { enc = e4m3(amax / E.qmax / sT); s = enc * sT; }
    }
    const limit = s * (E.qmax + E.over);
    let clipped = 0, gErr = 0;
    for (let i = start; i < end; i++) {
      const q = s > 0 ? E.round(x[i] / s) : 0;
      xhat[i] = q * s;
      err[i] = Math.abs(x[i] - xhat[i]);
      clip[i] = Math.abs(x[i]) > limit;
      if (clip[i]) clipped++;
      gErr = Math.max(gErr, err[i]);
      se += err[i] * err[i];
      sx += x[i] * x[i];
    }
    maxErr = Math.max(maxErr, gErr);
    groups.push({ k, start, end, amax, s, enc, clipped, maxErr: gErr });
  }
  return { xhat, err, clip, groups, rel: Math.sqrt(se / sx), bEff: E.bits + SCALE_BITS[sf] / size, sT, maxErr };
}

const memo = new Map<string, Result>();
function result(vec: Vec, elem: Elem, size: number, sf: ScaleFmt): Result {
  const key = `${vec}|${elem}|${size}|${sf}`;
  let r = memo.get(key);
  if (!r) {
    r = quantize(VECTORS[vec], elem, size, sf);
    if (memo.size > 64) memo.clear();
    memo.set(key, r);
  }
  return r;
}

// Error axis of the strip: fixed per vector, so switching formats compares
// like with like. The largest error of any combination the controls reach
// sets it.
const ceilings = new Map<Vec, number>();
function errorCeiling(vec: Vec): number {
  let m = ceilings.get(vec);
  if (m === undefined) {
    m = 0;
    const x = VECTORS[vec];
    for (const e of ["int4", "e2m1", "e4m3"] as Elem[]) for (const size of [16, 32, 128, N]) for (const sf of ["fp32", "fp16", "e8m0", "e4m3"] as ScaleFmt[]) {
      m = Math.max(m, quantize(x, e, size, sf).maxErr);
    }
    ceilings.set(vec, m);
  }
  return m;
}

// ---------------------------------------------------------------- math text

// "_x" or "_{...}" sets a subscript and "^{...}" a superscript as tspans.
interface MRun { s: string; level: number }
function parseMath(src: string, level = 0, out: MRun[] = []): MRun[] {
  const ch = [...src];
  let buf = "";
  const flush = () => { if (buf) { out.push({ s: buf, level }); buf = ""; } };
  for (let i = 0; i < ch.length;) {
    const c = ch[i];
    if ((c === "_" || c === "^") && i + 1 < ch.length) {
      flush();
      const lv = c === "_" ? 1 : -1;
      if (ch[i + 1] === "{") {
        let depth = 1, j = i + 2;
        while (j < ch.length && depth) { if (ch[j] === "{") depth++; else if (ch[j] === "}") depth--; j++; }
        out.push({ s: ch.slice(i + 2, j - 1).join(""), level: lv });
        i = j;
      } else { out.push({ s: ch[i + 1], level: lv }); i += 2; }
    } else { buf += c; i++; }
  }
  flush();
  return out;
}
const subSize = (size: number) => Math.max(TYPE.body, Math.round(size * 0.8));
function mathWidth(src: string, size: number): number {
  return parseMath(src).reduce((a, r) => a + textWidth(r.s, r.level === 0 ? size : subSize(size)), 0);
}
function mtext(x: number, y: number, src: string, size: number, attrs: Record<string, string | number | undefined> = {}): string {
  let cur = 0, inner = "";
  for (const r of parseMath(src)) {
    const off = r.level === 0 ? 0 : r.level < 0 ? -size * 0.38 : size * 0.3;
    const dy = off - cur;
    cur = off;
    inner += `<tspan${dy ? ` dy="${Math.round(dy * 10) / 10}"` : ""}${r.level ? ` font-size="${subSize(size)}"` : ""}>${esc(r.s)}</tspan>`;
  }
  return el("text", { x, y, "font-size": size, ...attrs }, inner);
}

// A wrapping legend whose labels may carry subscripts (lib/legend.ts sets
// plain text only).
type Swatch = { kind: "rect"; fill: string } | { kind: "line"; stroke: string } | { kind: "dot"; fill: string };
function mlegend(items: Array<{ label: string; swatch: Swatch }>, x: number, y: number, maxW: number, size: number = TYPE.body): { svg: string; height: number } {
  const rowH = size + 10;
  let cx = x, row = 0;
  const parts: string[] = [];
  for (const it of items) {
    const w = size + 6 + mathWidth(it.label, size);
    if (cx > x && cx + w > x + maxW) { row++; cx = x; }
    const base = y + row * rowH + size;
    const sw = it.swatch;
    if (sw.kind === "rect") parts.push(el("rect", { x: cx, y: base - size + 2, width: size, height: size - 2, rx: 2, fill: sw.fill }));
    else if (sw.kind === "line") parts.push(el("line", { x1: cx, x2: cx + size, y1: base - size / 2 + 1, y2: base - size / 2 + 1, stroke: sw.stroke, "stroke-width": 2, "stroke-linecap": "round" }));
    else parts.push(el("circle", { cx: cx + size / 2, cy: base - size / 2 + 1, r: size / 2 - 1.5, fill: sw.fill }));
    parts.push(mtext(cx + size + 6, base, it.label, size, { class: "fig-t-muted" }));
    cx += w + 14;
  }
  return { svg: el("g", { class: "fig-legend" }, ...parts), height: (row + 1) * rowH };
}

// ---------------------------------------------------------------- labels

