    summary: "{vec}: {bits} bits per value, relative error {rel}",
    ovTitle: "The 896 values x_i and each group's range ±q_{max} s_g",
    errTitle: "error |x_i − x̂_i|",
    channel: "channel",
    lgValue: "x_i",
    lgRange: "±q_{max} s_g",
    lgErr: "|x_i − x̂_i|",
    lgClip: "clipped",
    zTitle: "Group {k} of {G}, channels {a} to {b}",
    zTitleAll: "One group, all {n} channels",
    lgStored: "stored x̂_i = s_g q_i",
    lgGrid: "representable s_g q",
    amax: "amax",
    qInt4: "q: the integers −7 to 7",
    qE2m1: "q: 0, ±0.5, ±1, ±1.5, ±2, ±3, ±4, ±6",
    qE4m3: "q: the 253 FP8 E4M3 values up to ±448",
    clipped: "{n} of {g} values clipped to ±q_{max} s_g",
    bitsUnit: "bits per value",
    plusT: "plus one FP32 s_T for the tensor",
    bound: "≤ s_g / 2 = {b}",
