    cur: "current setting",
    bBits: "{b} bits per value",
    "int4-row": "INT4, one FP16 scale",
    "int4-g128": "INT4, g = 128, FP16 scales",
    mxfp4: "MXFP4",
    nvfp4: "NVFP4",
