    bBits: "每个值 {b} 比特",
    "int4-row": "INT4，一个 FP16 缩放因子",
    "int4-g128": "INT4，g = 128，FP16 缩放因子",
    mxfp4: "MXFP4",
    nvfp4: "NVFP4",
    "fp8-row": "FP8 E4M3，一个 FP32 缩放因子",
